{"explanation":"For a normal distribution, about 68% of the data falls within 1 standard deviation (σ) of the mean μ, about 95% within 2σ, and about 99.7% within 3σ. The animation shades these three nested bands one at a time and labels the percentage in each slice. The two slices just outside ±1σ hold about 13.6% each, and the slices between 2σ and 3σ hold about 2.1% each. Afterward, drag the slider to pick any number of standard deviations k and see the exact share of data within μ ± kσ.","manimCode":"const ax = new Axes({ xRange: [-4, 4, 1], yRange: [0, 0.5, 0.1], xLength: 10, yLength: 4.5, tips: false });
ax.moveTo([0, -0.9, 0]);
const pdf = x => Math.exp(-x * x / 2) / Math.sqrt(2 * Math.PI);
const curve = ax.plot(pdf, { color: WHITE, xRange: [-4, 4], numSamples: 300 });

function erf(x) {
  const s = x < 0 ? -1 : 1; x = Math.abs(x);
  const t = 1 / (1 + 0.3275911 * x);
  const y = 1 - (((((1.061405429 * t - 1.453152027) * t) + 1.421413741) * t - 0.284496736) * t + 0.254829592) * t * Math.exp(-x * x);
  return s * y;
}

const title = new Text({ text: 'The 68-95-99.7 Rule', color: WHITE, fontSize: 36 });
title.moveTo([0, 3.4, 0]);
scene.add(title);
await scene.play(new Create(ax));

// sigma tick labels
const ticks = [];
for (let k = -3; k <= 3; k++) {
  const lbl = k === 0 ? '\\mu' : '\\mu' + (k > 0 ? '+' : '-') + (Math.abs(k) === 1 ? '' : Math.abs(k)) + '\\sigma';
  const t = new MathTex({ latex: lbl, color: GRAY_A });
  await t.waitForRender();
  t.scale(0.55);
  const p = ax.c2p(k, 0);
  t.moveTo([p[0], p[1] - 0.35, 0]);
  ticks.push(t);
}
await scene.play(new AnimationGroup([new Create(curve), ...ticks.map(t => new FadeIn(t))]));

const a3 = ax.getArea(curve, [-3, 3], { color: BLUE_E, opacity: 0.5 });
const a2 = ax.getArea(curve, [-2, 2], { color: BLUE_C, opacity: 0.5 });
const a1 = ax.getArea(curve, [-1, 1], { color: TEAL, opacity: 0.6 });

async function mk(latex, color, pos) {
  const m = new MathTex({ latex, color });
  await m.waitForRender();
  m.scale(0.7);
  m.moveTo(pos);
  return m;
}
const L1 = await mk('\\mu \\pm 1\\sigma:\\ 68\\%', TEAL, [-4, 2.6, 0]);
const L2 = await mk('\\mu \\pm 2\\sigma:\\ 95\\%', BLUE_C, [0, 2.6, 0]);
const L3 = await mk('\\mu \\pm 3\\sigma:\\ 99.7\\%', BLUE_B, [4, 2.6, 0]);

function pct(str, x, y, fs) {
  const t = new Text({ text: str, color: WHITE, fontSize: fs || 20 });
  t.moveTo(ax.c2p(x, y));
  return t;
}
const p1 = [pct('34.1%', -0.5, 0.15), pct('34.1%', 0.5, 0.15)];
const p2 = [pct('13.6%', -1.5, 0.05, 16), pct('13.6%', 1.5, 0.05, 16)];
const p3 = [pct('2.1%', -2.5, 0.07, 16), pct('2.1%', 2.5, 0.07, 16)];

await scene.play(new FadeIn(a1));
await scene.play(new AnimationGroup([new Write(L1), ...p1.map(p => new FadeIn(p))]));
await scene.wait(0.6);
await scene.play(new FadeIn(a2));
await scene.play(new AnimationGroup([new Write(L2), ...p2.map(p => new FadeIn(p))]));
await scene.wait(0.6);
await scene.play(new FadeIn(a3));
await scene.play(new AnimationGroup([new Write(L3), ...p3.map(p => new FadeIn(p))]));
await scene.wait(1);

// Interactive part: slider for k
let k = 1;
let kArea = null;
let kLabel = null;
const leftLine = new Polygon({ vertices: [ax.c2p(-1, 0), ax.c2p(-1, pdf(1))], color: YELLOW });
leftLine.setStrokeWidth(4); leftLine.setFillOpacity(0);
const rightLine = new Polygon({ vertices: [ax.c2p(1, 0), ax.c2p(1, pdf(1))], color: YELLOW });
rightLine.setStrokeWidth(4); rightLine.setFillOpacity(0);

function refresh() {
  if (kArea) scene.remove(kArea);
  if (kLabel) scene.remove(kLabel);
  kArea = ax.getArea(curve, [-k, k], { color: YELLOW, opacity: 0.25 });
  leftLine.setVertices([ax.c2p(-k, 0), ax.c2p(-k, pdf(k))]);
  rightLine.setVertices([ax.c2p(k, 0), ax.c2p(k, pdf(k))]);
  const p = (erf(k / Math.SQRT2) * 100).toFixed(2);
  kLabel = new Text({ text: 'Within μ ± ' + k.toFixed(2) + 'σ:  ' + p + '%', color: YELLOW, fontSize: 26 });
  kLabel.moveTo([0, 1.9, 0]);
  scene.add(kArea, kLabel);
}
scene.add(leftLine, rightLine);
refresh();

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addSlider({ label: 'k (std devs)', min: 0.05, max: 4, value: 1, step: 0.05, onChange: v => { k = v; refresh(); } });
controls.addButton({ label: '1σ', onClick: () => { k = 1; refresh(); } });
controls.addButton({ label: '2σ', onClick: () => { k = 2; refresh(); } });
controls.addButton({ label: '3σ', onClick: () => { k = 3; refresh(); } });

await scene.wait(999999);"}

